#!/usr/bin/env bash
# Put the third-party files the web pages use into app/static/:
#   app/static/vendor/chart.umd.min.js      Chart.js (the charts)
#   app/static/fonts/*.woff2 + fonts.css    Plus Jakarta Sans, JetBrains Mono
#
# The pages load nothing from the internet: these files are committed, so a
# deployment is `git pull` and a restart. Run this script only to change a
# version (edit the numbers and checksums below). Step by step:
# docs/frontend-build.md.
#
# Needs: bash, curl, tar, openssl, awk (all on any Linux or macOS machine).
# Downloads from registry.npmjs.org only; Node is not needed.
set -euo pipefail

CHART_JS_VERSION="4.6.1"
CHART_JS_SHA512="hJyniucsFmq//EvXYvJ6c6mahPoI3kaxdjVH8awTaJ/fDNWeSqqqArixMJWkWNN6fcYvPU3HneSANFNYtRi61g=="
FONTSOURCE_VERSION="5.3.0"
JAKARTA_SHA512="9WRw3G74Ve4cyPApAZSXLPY5DiLOZXDn7Q7dIBjFBpA0Pj56ljDItEdy2UUajjJxRuTg2HkMLO5C3K2nAQORWg=="
JETBRAINS_SHA512="fqDfB5I9f1p1TV486aUgB9t8zP84P0O1FtQR5Ol9vjwPy+S+EIGlVYm1cvj2W5shcZMTg2nZFdVMoH5wFu8a1A=="
# The weights the pages use (base.html's font stacks), latin + latin-ext only.
JAKARTA_WEIGHTS="400 500 600 700 800"
JETBRAINS_WEIGHTS="400 500"

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
STATIC="$ROOT/app/static"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

# fetch <npm tarball url> <expected sha512, base64> <directory to unpack into>
fetch() {
    local url="$1" want="$2" dest="$3" got
    echo "Downloading $url"
    curl -fsSL "$url" -o "$WORK/pkg.tgz"
    got="$(openssl dgst -sha512 -binary "$WORK/pkg.tgz" | openssl base64 -A)"
    if [ "$got" != "$want" ]; then
        echo "Checksum mismatch for $url" >&2
        echo "  expected $want" >&2
        echo "  got      $got" >&2
        exit 1
    fi
    mkdir -p "$dest"
    tar -xzf "$WORK/pkg.tgz" -C "$dest"
}

# fonts <npm name> <file prefix> <sha512> <weights> <license file name>
fonts() {
    local name="$1" prefix="$2" sha="$3" weights="$4" license="$5" w
    fetch "https://registry.npmjs.org/@fontsource/$name/-/$name-$FONTSOURCE_VERSION.tgz" "$sha" "$WORK/$name"
    local pkg="$WORK/$name/package"
    for w in $weights; do
        cp "$pkg/files/$prefix-latin-$w-normal.woff2" "$pkg/files/$prefix-latin-ext-$w-normal.woff2" "$STATIC/fonts/"
        # Keep the latin and latin-ext @font-face blocks of the package's
        # stylesheet, woff2 only, with the files next to fonts.css.
        awk -v keep1="$prefix-latin-$w-normal" -v keep2="$prefix-latin-ext-$w-normal" '
            BEGIN { RS = ""; ORS = "\n\n" }
            index($0, "/* " keep1 " */") || index($0, "/* " keep2 " */") { print }
        ' "$pkg/$w.css" \
            | sed -e 's#url(./files/#url(./#g' -e "s#, url([^)]*\.woff) format('woff')##g" \
            >> "$WORK/fonts.css"
    done
    cp "$pkg/LICENSE" "$STATIC/fonts/$license"
}

rm -rf "$STATIC/vendor" "$STATIC/fonts"
mkdir -p "$STATIC/vendor" "$STATIC/fonts"

fetch "https://registry.npmjs.org/chart.js/-/chart.js-$CHART_JS_VERSION.tgz" "$CHART_JS_SHA512" "$WORK/chartjs"
# Without the source-map comment: the .map file is not shipped, and the
# browser's developer tools would ask for it on every page.
grep -v '^//# sourceMappingURL=' "$WORK/chartjs/package/dist/chart.umd.min.js" > "$STATIC/vendor/chart.umd.min.js"
cp "$WORK/chartjs/package/LICENSE.md" "$STATIC/vendor/chart.js-LICENSE.md"

{
    echo "/* Generated by scripts/vendor_frontend.sh from @fontsource $FONTSOURCE_VERSION: do not edit. */"
    echo
} > "$WORK/fonts.css"
fonts plus-jakarta-sans plus-jakarta-sans "$JAKARTA_SHA512" "$JAKARTA_WEIGHTS" "PlusJakartaSans-OFL.txt"
fonts jetbrains-mono jetbrains-mono "$JETBRAINS_SHA512" "$JETBRAINS_WEIGHTS" "JetBrainsMono-OFL.txt"
cp "$WORK/fonts.css" "$STATIC/fonts/fonts.css"

echo
echo "Done. Chart.js $CHART_JS_VERSION and the fonts are in app/static/."
echo "Check the pages, then commit app/static/vendor and app/static/fonts."
